// Created: 2026-07-26

/**
 * Unit tests for visual-style-nudge (UserPromptSubmit sub-hook)
 *
 * Re-anchors the visual-style rule on prompts that want a shaped answer.
 * The throttle is the load-bearing behaviour: firing once per session would
 * reproduce the decay this hook exists to fix, and firing every turn would be
 * noise, so it must fire on the 1st qualifying prompt and periodically after.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { HookInput } from '../../types.js';
import { visualStyleNudge } from '../../prompt/visual-style-nudge.js';

let dir: string;
let session = 0;

// CLAUDE_PLUGIN_DATA is the var getSessionStorageDir() actually honors. An
// earlier draft of this file set CLAUDE_SESSION_STORAGE_DIR, which is read by
// nothing — the throttle counters were written into the real
// src/hooks/.claude/memory/sessions/ and survived between runs, so the suite
// passed once on a clean tree and then failed on every rerun. Isolation here
// is load-bearing, not hygiene: the whole point of these tests is counting.
beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'viz-nudge-'));
  process.env.CLAUDE_PLUGIN_DATA = dir;
  session += 1;
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
  delete process.env.CLAUDE_PLUGIN_DATA;
});

function prompt(text: string, sid = `s-${session}`): HookInput {
  return { tool_name: '', session_id: sid, prompt: text, tool_input: {} } as unknown as HookInput;
}

function fired(r: ReturnType<typeof visualStyleNudge>): boolean {
  const out = r.hookSpecificOutput as { additionalContext?: string } | undefined;
  return typeof out?.additionalContext === 'string' && out.additionalContext.includes('visual-style-nudge');
}

describe('visual-style-nudge', () => {
  it('fires on an explicit visualization ask', () => {
    expect(fired(visualStyleNudge(prompt('can you vis this in ascii emojies')))).toBe(true);
  });

  it('fires on implicit shape requests (the decay case)', () => {
    for (const p of ['what is the status of the migration', 'compare these two approaches for me', 'what are my options here', 'explain how the dispatcher works']) {
      session += 1;
      expect(fired(visualStyleNudge(prompt(p, `s-${session}`)))).toBe(true);
    }
  });

  it('stays silent on prompts with no shape', () => {
    expect(fired(visualStyleNudge(prompt('rename this variable to userCount')))).toBe(false);
  });

  it('stays silent on very short prompts', () => {
    expect(fired(visualStyleNudge(prompt('status')))).toBe(false);
  });

  it('stays silent when the user already routed to a skill', () => {
    expect(fired(visualStyleNudge(prompt('/ork:assess the current status of things')))).toBe(false);
  });

  it('throttles: fires on the 1st qualifying prompt, not the 2nd', () => {
    const sid = 'throttle-a';
    expect(fired(visualStyleNudge(prompt('what is the status here', sid)))).toBe(true);
    expect(fired(visualStyleNudge(prompt('and the status of the other one', sid)))).toBe(false);
  });

  it('RE-ANCHORS periodically — this is the whole point vs a once-per-session nudge', () => {
    const sid = 'throttle-b';
    const results: boolean[] = [];
    for (let i = 0; i < 17; i++) {
      results.push(fired(visualStyleNudge(prompt('what is the status of things', sid))));
    }
    // Fires at prompt 1, 9, 17 (every 8th) — not once, not every time.
    expect(results.filter(Boolean).length).toBeGreaterThan(1);
    expect(results[0]).toBe(true);
    expect(results.filter(Boolean).length).toBeLessThan(results.length);
  });

  it('counts sessions independently', () => {
    expect(fired(visualStyleNudge(prompt('what is the status here', 'sess-1')))).toBe(true);
    expect(fired(visualStyleNudge(prompt('what is the status here', 'sess-2')))).toBe(true);
  });

  it('does not throw on a path-traversal session id', () => {
    const evil = '../../../etc/passwd';
    expect(() => visualStyleNudge(prompt('what is the status here', evil))).not.toThrow();
  });

  it('REGRESSION: consecutive fires emit DIFFERENT text (defeats dispatcher delta-skip)', () => {
    // unified-dispatcher runs delta detection on the consolidated context and
    // silently drops a turn whose output is byte-identical to the previous one
    // (unified-dispatcher.ts, prompt-hash.txt). A constant message is therefore
    // injected exactly ONCE per session and every later re-anchor is swallowed,
    // reproducing the decay this hook exists to fix. Measured through the real
    // dispatcher before the fix: 1/20 fires. After: 3/20, at prompts 1/9/17.
    const sid = 'delta-skip';
    const messages: string[] = [];
    for (let i = 0; i < 17; i++) {
      const r = visualStyleNudge(prompt('what is the status of things', sid));
      const c = (r.hookSpecificOutput as { additionalContext?: string })?.additionalContext;
      if (c) messages.push(c);
    }
    expect(messages.length).toBeGreaterThan(1); // it re-anchors at all
    expect(new Set(messages).size).toBe(messages.length); // and never repeats itself
  });

  it('names the sub-agent non-inheritance caveat (the second diagnosed gap)', () => {
    const r = visualStyleNudge(prompt('show me the comparison please', 'caveat-1'));
    const out = r.hookSpecificOutput as { additionalContext?: string };
    expect(out.additionalContext).toMatch(/[Ss]ub-agents do not inherit/);
  });
});
